#define _GNU_SOURCE
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <sched.h>

int main() {
    pthread_attr_t attr;
    struct sched_param param;
    int policy;
    int ret;

    // 1. Initialize the attributes object
    if ((ret = pthread_attr_init(&attr)) != 0) {
        fprintf(stderr, "Error initializing attributes: %d\n", ret);
        return 1;
    }

    // 2. Set the policy to SCHED_RR (a real-time policy) to allow priority setting
    policy = SCHED_RR;
    if ((ret = pthread_attr_setschedpolicy(&attr, policy)) != 0) {
        fprintf(stderr, "Error setting scheduling policy: %d\n", ret);
        goto cleanup;
    }

    // 3. Set inheritance attribute to explicit scheduling
    if ((ret = pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED)) != 0) {
        fprintf(stderr, "Error setting inheritance attribute: %d\n", ret);
        goto cleanup;
    }

    // Determine a valid priority range for the chosen policy
    int max_prio = sched_get_priority_max(policy);
    int min_prio = sched_get_priority_min(policy);
    int desired_prio = (max_prio + min_prio) / 2; // Mid-range priority

    // 4. Set the desired scheduling parameter (priority)
    param.sched_priority = desired_prio;
    if ((ret = pthread_attr_setschedparam(&attr, &param)) != 0) {
        fprintf(stderr, "Error setting scheduling parameters (priority %d): %d\n", desired_prio, ret);
        goto cleanup;
    }

    // 5. Verify the setting using getschedparam
    struct sched_param verify_param;
    if ((ret = pthread_attr_getschedparam(&attr, &verify_param)) != 0) {
        fprintf(stderr, "Error getting scheduling parameters: %d\n", ret);
        goto cleanup;
    }

    printf("Successfully set and retrieved priority.\n");
    printf("Verified priority in attribute object: %d (Expected: %d)\n", 
           verify_param.sched_priority, desired_prio);

cleanup:
    pthread_attr_destroy(&attr);
    return ret == 0 ? 0 : 1;
}
